-- fdh-c-check: op row count of AER
-- GENERATED by scripts/export_rules.mjs from BKH Insight src/app/api/fdh/c-check/checks.ts - do not edit by hand
-- params (2, in order of the placeholders): start, end
-- returns n
WITH p AS (SELECT CAST(? AS DATE) AS s, CAST(? AS DATE) AS e) SELECT COUNT(*) AS n FROM p JOIN er_regist er ON er.vstdate BETWEEN p.s AND p.e INNER JOIN ovst v ON v.vn = er.vn LEFT JOIN referout rout ON rout.vn = er.vn WHERE v.an IS NULL OR v.an = '';
